def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    # Detect exploitation: opponent defected while we cooperated
    if last_me == 'C' and last_opp == 'D':
        # Punish, but only briefly if they seem otherwise cooperative
        if opp_c * 2 > n:
            # Occasional quick forgiveness to avoid lock-in
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        return 'D'

    # If both defected last round, try to break spiral
    if last_me == 'D' and last_opp == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and opp[i] == 'D':
                run += 1
            else:
                break
        if run >= 3 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Last round we defected, opponent cooperated: return to cooperation
    if last_me == 'D' and last_opp == 'C':
        # Unless opponent is a heavy defector overall
        if opp_d * 2 > n:
            return 'D'
        return 'C'

    # Opponent cooperated last, we cooperated last
    # Opponent has never defected
    if opp_d == 0:
        if n == 99:
            return 'D'
        # Rare probe to test for exploitability, not too late
        if n in (30, 60) and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent has defected at least once; assess recent behavior
    recent = opp[-10:] if n >= 10 else opp
    recent_d = recent.count('D')

    if recent_d >= 7:
        return 'D'
    if recent_d >= 4:
        # Mixed: mirror-ish with occasional forgiveness
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    if recent_d >= 1:
        # Mostly cooperative lately: cooperate, but watch out
        return 'C'

    # Opponent cooperated a lot recently: cooperate, occasional probe
    if n >= 50 and n % 20 == 0:
        return 'D'
    return 'C'
